with FilteredAccounts as (select *, concat(account_type, '/', status) as account_type_status from accounts where status = 'CLOSED' and account_type = 'CREDIT'), account_type_summary as (select account_type, max(opened_date) as latest_opened_date, sum(case when account_type = 'LOAN' then 1 else 0 end) as loan_count from FilteredAccounts group by account_type) select account_type, latest_opened_date, loan_count from account_type_summary where loan_count >= 40 order by loan_count desc;
